/**
 * The system-prompt section that teaches a model the v10r catalog — generated by
 * `@a2ui/agent` from the catalog document, so the prompt and the validator can never
 * describe different catalogs.
 *
 * Express is the default: over the committed scenarios it costs 35–64 % of A2UI JSON's payload
 * tokens, and its catalog prompt about 40 % of the JSON prompt's (`bun run genui:bench`,
 * `scripts/generative-ui/bench-report.json`). JSON stays available for models that follow the
 * Express grammar poorly.
 *
 * The prompt is a constant per format and process, so it is built once and is a candidate for
 * the provider's prompt cache.
 */
import { A2uiGenerator, CatalogConfig, DirectJsonFormatFactory, ExpressFormatFactory } from '@a2ui/agent';
import { GENERATIVE_UI_CATALOG_ID } from '#lib/generative-ui/index.ts';
import { loadGenerativeUiCatalog } from '#lib/generative-ui/load-catalog.ts';

export type GenerativeSurfaceFormat = 'express' | 'json';

const prompts = new Map<GenerativeSurfaceFormat, string>();

export function buildGenerativeSurfacePrompt(format: GenerativeSurfaceFormat = 'express'): string {
	const cached = prompts.get(format);
	if (cached) return cached;
	const generator = new A2uiGenerator([new CatalogConfig(loadGenerativeUiCatalog())]);
	const factory = format === 'express' ? new ExpressFormatFactory() : new DirectJsonFormatFactory();
	const prompt = generator.createProcessor({ supportedCatalogIds: [GENERATIVE_UI_CATALOG_ID] }, factory).promptSnippet;
	prompts.set(format, prompt);
	return prompt;
}
